use xiom.io;

type Product = {
  name: Str;
  price: Float64;
  stock: Int;
  invariant: stock >= 0;
  invariant: price > 0.0;
}

fn sell(product: &mut Product, qty: Int)
  requires: qty > 0;
  requires: qty <= product.stock;
  ensures: product.stock == product@pre.stock - qty;
{
  product.stock = product.stock - qty;
}

fn show_product(product: &Product) -> Str {
  return product.name + ": $" + product.price;
}

fn main() -> Int {
  var p: Product = Product{ name: "Widget", price: 9.99, stock: 100 };
  sell(&mut p, 3);
  io.println(show_product(&p).to_str());
  return p.stock;
}
